 "content": "def transform(grid):
    """Extend rectangular 1-outlines into the surrounding 0-space, coloring
    the one-cell exterior border 2 and the enclosed interior 3."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Distinct enclosed zero regions become 3; their immediate 4-neighbor
    # exterior cells become 2. Use components to recognize closed outlines.
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r,c) in seen:
                continue
            comp=[]; stack=[(r,c)]; seen.add((r,c)); touches_edge=False
            while stack:
                y,x=stack.pop(); comp.append((y,x))
                if y==0 or x==0 or y==h-1 or x==w-1: touches_edge=True
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and grid[yy][xx]==0 and (yy,xx) not in seen:
                        seen.add((yy,xx)); stack.append((yy,xx))
            if not touches_edge:
                # likely enclosed interior; mark as 3
                for y,x in comp: out[y][x]=3
                for y,x in comp:
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        yy,xx=y+dy,x+dx
                        if 0<=yy<h and 0<=xx<w and grid[yy][xx]==0 and out[yy][xx]==0:
                            out[yy][xx]=2
    # Outside border is the exterior-side outline of the shape: mark 2 only
    # where zero touches a 1 at a boundary of an enclosed (rectangular) form.
    # The demo has an open top-right gap, so 2 is specifically on the outside
    # ring immediately surrounding the closed 1 boundary, derived by dilation.
    # Apply exterior 2 around 1 outlines when the region is adjacent to a closed
    # rectangular perimeter (including discontinuous interior shape segments).
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1:
                continue
            # blank neighboring cells remain available for exterior border.
            for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                rr,cc=r+dy,c+dx
                if 0<=rr<h and 0<=cc<w and grid[rr][cc]==0 and out[rr][cc]==0:
                    # Only designate as border if it is connected to exterior
                    # by zero cells (interior is already 3).
                    out[rr][cc]=2
    return out

if __name__ == '__main__':
    pass
