 "old_string": "    # Leave outlines alone if they are not a self-contained closed shape.
    # Closed shapes are 1-components with a zero cavity; color their outer
    # bounding rectangle halo 2 and cavity 3, preserving original center holes.
    seen = set()
    outline_cells = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            comp = []
            stack = [(r, c)]
            seen.add((r, c))
            touches_edge = False
            border_ones = set()
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                if y in (0, h - 1) or x in (0, w - 1):
                    touches_edge = True
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w:
                        if grid[yy][xx] == 0 and (yy, xx) not in seen:
                            seen.add((yy, xx))
                            stack.append((yy, xx))
                        elif grid[yy][xx] == 1:
                            border_ones.add((yy, xx))
            if not touches_edge:
                # Color each cell of the cavity with 3 except locations that
                # are part of a hole indicated by an internal 1-pattern.
                for y, x in comp:
                    out[y][x] = 3
                # Keep the componentwise bounding rectangle centerline holes
                # (the demo's intentional zero windows) unfilled.
                cy = sum(y for y, _ in comp) / len(comp)
                cx = sum(x for _, x in comp) / len(comp)
                for y, x in comp:
                    if (abs(y - cy) <= 0.5 and abs(x - cx) <= 0.5
                            and any(grid[yy][xx] == 1 for yy in range(max(0, y-1), min(h, y+2))
                                    for xx in range(max(0, x-1), min(w, x+2)))):
                        out[y][x] = 0
                outline_cells.update(border_ones)
    # Expand qualifying outlines through the 1-component and make the
    # surrounding bounding rectangle (one cell beyond the outline) color 2.
    active_ones = set()
    while outline_cells:
        start = outline_cells.pop()
        if start in active_ones:
