 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    enclosed = set()
    outline = set()
    # Enclosed 4-connected zero components are filled with 3. An opening in
    # a wireframe lets the zero component reach the canvas edge, so it stays 0.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            comp = []
            border_ones = set()
            stack = [(r, c)]
            seen.add((r, c))
            touches_edge = False
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                if y == 0 or y == h - 1 or x == 0 or x == w - 1:
                    touches_edge = True
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w:
                        if grid[yy][xx] == 0 and (yy, xx) not in seen:
                            seen.add((yy, xx))
                            stack.append((yy, xx))
                        elif grid[yy][xx] == 1:
                            border_ones.add((yy, xx))
            if not touches_edge:
                enclosed.update(comp)
                outline.update(border_ones)
                for y, x in comp:
                    out[y][x] = 3

    # Extend from enclosing edge cells over their connected 1-linework and
    # color its immediate outside halo 2. Do not overwrite enclosed fill.
    active_ones = set(outline)
    stack = list(outline)
    while stack:
        y, x = stack.pop()
        for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            yy, xx = y + dy, x + dx
            if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 1 and (yy, xx) not in active_ones:
                active_ones.add((yy, xx))
                stack.append((yy, xx))

    for y, x in active_ones:
        for dy in (-1, 0, 1):
            for dx in (-1, 0, 1):
                if dy == dx == 0:
                    continue
                yy, xx = y + dy, x + dx
                if (0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 0
                        and (yy, xx) not in enclosed):
                    out[yy][xx] = 2
    return out

