 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # First label 4-connected 1-objects.
    labels = {}
    objects = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or (r, c) in labels:
                continue
            cells = set()
            stack = [(r, c)]
            labels[(r, c)] = len(objects)
            while stack:
                y, x = stack.pop()
                cells.add((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 1
                            and (yy, xx) not in labels):
                        labels[(yy, xx)] = len(objects)
                        stack.append((yy, xx))
            objects.append(cells)

    # Locate enclosed 0-regions and associate their bordering 1-object(s).
    seen = set()
    qualifying = set()
    cavity_by_object = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            comp = []
            border_ids = set()
            stack = [(r, c)]
            seen.add((r, c))
            touches_edge = False
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                if y in (0, h - 1) or x in (0, w - 1):
                    touches_edge = True
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w:
                        if grid[yy][xx] == 0 and (yy, xx) not in seen:
                            seen.add((yy, xx))
                            stack.append((yy, xx))
                        elif grid[yy][xx] == 1:
                            border_ids.add(labels[(yy, xx)])
            if not touches_edge and border_ids:
                for oid in border_ids:
                    qualifying.add(oid)
                    cavity_by_object.setdefault(oid, []).append(comp)

    # Transform only objects enclosing a cavity. Put a 2 frame around their
    # complete bounding box; color one cell of the cavity's inner perimeter 3.
    for oid in qualifying:
        cells = objects[oid]
        min_y = min(y for y, x in cells)
        max_y = max(y for y, x in cells)
        min_x = min(x for y, x in cells)
        max_x = max(x for y, x in cells)
        for y in range(max(0, min_y - 1), min(h, max_y + 2)):
            for x in range(max(0, min_x - 1), min(w, max_x + 2)):
                if grid[y][x] == 0 and (y in (min_y - 1, max_y + 1) or x in (min_x - 1, max_x + 1)):
                    out[y][x] = 2
        for comp in cavity_by_object[oid]:
            for y, x in comp:
                if any(0 <= y + dy < h and 0 <= x + dx < w and grid[y + dy][x + dx] == 1
                       and labels[(y + dy, x + dx)] == oid
                       for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1))):
                    out[y][x] = 3
    return out

