 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    enclosed = set()
    outlines = []

    # Find every enclosed 0 component, which identifies a closed 1-object.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            comp = []
            border = set()
            stack = [(r, c)]
            seen.add((r, c))
            touches_edge = False
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                if y in (0, h - 1) or x in (0, w - 1):
                    touches_edge = True
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w:
                        if grid[yy][xx] == 0 and (yy, xx) not in seen:
                            seen.add((yy, xx))
                            stack.append((yy, xx))
                        elif grid[yy][xx] == 1:
                            border.add((yy, xx))
            if not touches_edge and border:
                enclosed.update(comp)
                outlines.append((comp, border))
                # Fill the whole interior 0 component; original 1s remain.
                for y, x in comp:
                    out[y][x] = 3

    # Each closed outline gets a 2 halo immediately outside the 1 cells.
    # Determine which neighbor is outside by membership in enclosed zero cells.
    for comp, border in outlines:
        for y, x in border:
            for dy in (-1, 0, 1):
                for dx in (-1, 0, 1):
                    if dy == dx == 0:
                        continue
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 0
                            and (yy, xx) not in enclosed):
                        out[yy][xx] = 2

    return out

