    out = [row[:] for row in grid]

    # Connected 1-components.
    labels = {}
    objects = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or (r, c) in labels:
                continue
            oid = len(objects)
            cells = set()
            stack = [(r, c)]
            labels[(r, c)] = oid
            while stack:
                y, x = stack.pop()
                cells.add((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 1
                            and (yy, xx) not in labels):
                        labels[(yy, xx)] = oid
                        stack.append((yy, xx))
            objects.append(cells)

    # Enclosed zero regions identify which 1-components form closed frames.
    qualifying = set()
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            comp = []
            border_ids = set()
            stack = [(r, c)]
            seen.add((r, c))
            edge = False
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                if y in (0, h - 1) or x in (0, w - 1):
